43	    /// class Foo { getStatus(b: boolean): string { if (b) return "loading"; return "idle"; } }
44	    /// ```
45	    ///
46	    /// ```ts,expect_diagnostic,file=invalid4.ts
47	    /// const obj = { getMode(b: boolean): string { if (b) return "dark"; return "light"; } };
48	    /// ```
49	    ///
50	    /// ```ts,expect_diagnostic,file=invalid5.ts
51	    /// function makeData(): object { return { retry: true }; }
52	    /// ```
53	    ///
54	    /// ### Valid
55	    ///
56	    /// ```ts
57	    /// function getStatus() { return "loading"; }
58	    /// ```
59	    ///
60	    /// ```ts
61	    /// function run(): void { return; }
62	    /// ```
63	    ///
64	    /// ```ts
65	    /// class Foo { greet(): string { return "hello"; } }
66	    /// ```
67	    ///
68	    /// ## Known limitations
69	    ///
70	    /// When a return uses a type assertion such as `as T`, the rule does
71	    /// not flag the return unless it can prove that `T` is narrower than
72	    /// `object`. Trusted cases include `unknown`, `any`, `typeof` queries,
73	    /// conditional types, generic type parameters, and types the rule
74	    /// cannot resolve. Intersections (`A & B`) are trusted when every
75	    /// member is or when any member is `any`; unions (`A | B`) when at
76	    /// least one is.
