/// expression types, for use in a non-union annotation's diagnostic note.
///
/// Only string, number, and boolean literals are rendered; any other kind of
/// return type yields `None`, which produces the generic narrowing note.
fn build_inferred_description(returns: &[Type]) -> Option<String> {
    let mut out = String::new();
    let mut has_any = false;
    for ty in returns {
        let TypeData::Literal(lit) = &**ty else {
            return None;
        };
        if has_any {
            out.push_str(" | ");
        }
        has_any = true;
        match lit.as_ref() {
            Literal::String(s) => {
                let text = s.as_str();
                // Skip values that would look confusing in a diagnostic (e.g. "...").
                if text.contains("...")
                    || text.contains("__internal")
                    || text.contains("typeof import(")
                {
                    return None;
                }
                out.push('"');
                out.push_str(text);
                out.push('"');
            }
            Literal::Number(n) => out.push_str(n.as_str()),
            Literal::Boolean(b) => out.push_str(if b.as_bool() { "true" } else { "false" }),
            _ => return None,
        }
        // Skip overly long descriptions.
        if out.len() > MAX_DESCRIPTION_LENGTH {
            return None;
        }
    }
    if !has_any {
        return None;
    }
    Some(out)
}

/// Builds a narrower suggestion for a union annotation from the union variants
/// that are actually covered by at least one return statement.
///
/// Returns `None` (falling back to the generic narrowing note) when any covered
/// variant cannot be rendered as a concrete type name, when no variant is
/// covered, or when the rendered suggestion would exceed
/// [`MAX_DESCRIPTION_LENGTH`].
fn build_union_suggestion(annotation: &Type, returns: &[Type]) -> Option<String> {
    let mut out = String::new();
    let mut has_any = false;
    for variant in annotation.flattened_union_variants() {
        let covered = returns
            .iter()
            .any(|ret| types_match(&variant, ret) || is_nonunion_wider(&variant, ret));
        if !covered {
            continue;
        }
        let rendered = render_type_name(&variant)?;
        if has_any {
            out.push_str(" | ");
        }
        has_any = true;
        out.push_str(&rendered);
        if out.len() > MAX_DESCRIPTION_LENGTH {
            return None;
        }
    }
    if !has_any {
        return None;
    }
    Some(out)
}

