/// Whether a union annotation should never be flagged as misleadingly wide.
///
/// A union is exempt when it contains `any`, `unknown`, or `never` as a
/// variant (those absorb or vanish, leaving no meaningful narrowing), or when
/// every variant belongs to the same primitive family and the union therefore
/// collapses to a single primitive (e.g. `"a" | string`, `1 | 2 | number`,
/// `1n | bigint`).
fn union_annotation_is_exempt(annotation: &Type) -> bool {
    if annotation.flattened_union_variants().any(|variant| {
        matches!(
            &*variant,
            TypeData::AnyKeyword
                | TypeData::UnknownKeyword
                | TypeData::Unknown
                | TypeData::NeverKeyword
        )
    }) {
        return true;
    }

    union_collapses_to_single_primitive(annotation)
}

/// Whether every variant of the union is either a primitive keyword or a
/// literal of that same primitive, so the union collapses to one primitive and
/// no narrowing is meaningful. Requires both a bare primitive keyword and at
/// least one literal to be present (a pure literal union like `"a" | "b"` does
/// not collapse).
fn union_collapses_to_single_primitive(annotation: &Type) -> bool {
    let mut family: Option<PrimitiveFamily> = None;
    let mut has_primitive_keyword = false;
    let mut has_literal = false;

    for variant in annotation.flattened_union_variants() {
        let (variant_family, is_keyword) = match &*variant {
            TypeData::String => (PrimitiveFamily::String, true),
            TypeData::Number => (PrimitiveFamily::Number, true),
            TypeData::Boolean => (PrimitiveFamily::Boolean, true),
            TypeData::BigInt => (PrimitiveFamily::BigInt, true),
            TypeData::Literal(lit) => match lit.as_ref() {
                Literal::String(_) | Literal::Template(_) => (PrimitiveFamily::String, false),
                Literal::Number(_) => (PrimitiveFamily::Number, false),
                Literal::Boolean(_) => (PrimitiveFamily::Boolean, false),
                Literal::BigInt(_) => (PrimitiveFamily::BigInt, false),
                _ => return false,
            },
            _ => return false,
        };

        if is_keyword {
            has_primitive_keyword = true;
        } else {
            has_literal = true;
        }

        match family {
            None => family = Some(variant_family),
            Some(existing) if existing == variant_family => {}
            Some(_) => return false,
        }
    }

    family.is_some() && has_primitive_keyword && has_literal
}

