    AnalysisFilter, AnalyzerConfiguration, AnalyzerOptions, ControlFlow, Never, RuleFilter,
};
use biome_diagnostics::{Diagnostic, DiagnosticExt, Severity, print_diagnostic_to_string};
use biome_fs::TemporaryFs;
use biome_js_analyze::{JsAnalyzerServices, analyze};
use biome_js_parser::{JsParserOptions, parse};
use biome_js_semantic::{SemanticModelOptions, semantic_model};
use biome_js_syntax::JsFileSource;
use biome_project_layout::ProjectLayout;
use biome_test_utils::module_graph_for_test_file;
use camino::Utf8PathBuf;
use std::slice;
use std::sync::Arc;

fn check(label: &str, source: &str) {
    const FILENAME: &str = "probe.ts";
    let parsed = parse(source, JsFileSource::ts(), JsParserOptions::default());

    let mut fs = TemporaryFs::new("probe_mrt");
    fs.create_file(FILENAME, source);
    let file_path = Utf8PathBuf::from(format!("{}/{FILENAME}", fs.cli_path()));

    let options = AnalyzerOptions::default().with_file_path(file_path.clone());
    let rule_filter = RuleFilter::Rule("nursery", "noMisleadingReturnType");

    let project_layout = Arc::new(ProjectLayout::default());
    let semantic_model = semantic_model(&parsed.tree(), SemanticModelOptions::default());
    let services = JsAnalyzerServices::from((
        module_graph_for_test_file(file_path.as_path(), project_layout.as_ref()),
        project_layout,
        JsFileSource::ts(),
        Some(semantic_model),
    ));

    let mut notes: Vec<String> = Vec::new();
    analyze(
        &parsed.tree(),
        AnalysisFilter {
            enabled_rules: Some(slice::from_ref(&rule_filter)),
            ..AnalysisFilter::default()
        },
        &options,
        &[],
        services,
        |signal| {
            if let Some(diag) = signal.diagnostic() {
                let error = diag
                    .with_severity(Severity::Warning)
                    .with_file_path(FILENAME)
                    .with_file_source_code(source);
                notes.push(print_diagnostic_to_string(&error));
            }
            ControlFlow::<Never>::Continue(())
        },
    );

    print!("### {label}: ");
    if notes.is_empty() {
        println!("NOT FLAGGED");
    } else {
        println!("FLAGGED");
        for n in &notes {
            for line in n.lines() {
                let t = line.trim();
                if t.starts_with("i ") {
                    println!("    {t}");
                }
            }
        }
    }
}

fn main() {
    // R10: literal|primitive collapse — must NOT be flagged
    check("R10 a|string single", r#"function f(): "a" | string { return "a"; }"#);
    check(
        "R10 a|b|string multi",
        r#"function f(x: boolean): "a" | "b" | string { if (x) return "a"; return "b"; }"#,
    );
    check(
        "R10 1|2|number",
        r#"function f(x: boolean): 1 | 2 | number { if (x) return 1; return 2; }"#,
    );
    check(
        "R10 bare string for a|string",
        r#"declare const s: string; function f(): "a" | string { return s; }"#,
    );
    // R8/R9: any/unknown/never variants — must NOT be flagged
    check(
        "R8 any variant",
        r#"function f(x: boolean): string | any { if (x) return "a"; return "b"; }"#,
    );
    check(
        "R8 unknown variant",
        r#"function f(x: boolean): string | unknown { if (x) return "a"; return "b"; }"#,
    );
    check(
        "R9 never variant",
        r#"function f(x: boolean): string | never { if (x) return "a"; return "b"; }"#,
    );
    // R3: concrete suggestions
    check(
        "R3 union subset literals",
        r#"function f(x: boolean): "a" | "b" | "c" { if (x) return "a"; return "b"; }"#,
    );
    check(
        "R3 string variant covered, number never",
        r#"declare const s: string; function f(x: boolean): string | number { if (x) return s; return s; }"#,
    );
    // R7: throwing branch does not count
    check(
        "R7 throw branch",
        r#"function f(x: boolean): "a" | "b" | "c" { if (x) return "a"; if (!x) return "b"; throw new Error(); }"#,
    );
    // R4: async promise union
    check(
        "R4 async promise union",
        r#"async function f(x: boolean): Promise<"a" | "b" | "c"> { if (x) return "a"; return "b"; }"#,
    );
    // R6: type alias resolving to union
    check(
        "R6 alias union",
        r#"type U = "a" | "b" | "c"; function f(x: boolean): U { if (x) return "a"; return "b"; }"#,
    );
    // Sanity: all variants covered -> NOT flagged
    check(
        "sanity all covered",
        r#"function f(x: boolean): "a" | "b" { if (x) return "a"; return "b"; }"#,
    );
    // boolean exhausted union with extra -> NOT flagged (both true and false + extra covered)
    check(
        "sanity boolean exhausted",
        r#"function f(x: boolean): boolean | "skip" { if (x) return true; if (!x) return false; return "skip"; }"#,
    );
}
