195	/// Looks for sibling function declarations with the same name but no body,
196	/// which indicates this function is the implementation of an overload set.
197	/// Overload signatures are parsed as `TsDeclareFunctionDeclaration` or as
198	/// `AnyJsFunction` with `body().is_err()`.
199	fn is_overload_implementation(node: &AnyJsFunction) -> bool {
200	    let name = node
201	        .binding()
202	        .and_then(|b| b.as_js_identifier_binding().cloned())
203	        .and_then(|id| id.name_token().ok())
204	        .map(|t| t.token_text_trimmed());
205	    let Some(name) = name else { return false };
206	
207	    let Some(parent) = node.syntax().parent() else {
208	        return false;
209	    };
210	    parent.children().any(|sibling| {
211	        if sibling == *node.syntax() {
212	            return false;
213	        }
214	        if let Some(decl) =
215	            TsDeclareFunctionDeclaration::cast(sibling.clone())
216	        {
217	            return decl
218	                .id()
219	                .ok()
220	                .and_then(|id| id.as_js_identifier_binding().cloned())
221	                .and_then(|id| id.name_token().ok())
222	                .is_some_and(|t| t.token_text_trimmed() == name);
223	        }
224	        AnyJsFunction::cast(sibling).is_some_and(|sib_fn| {
225	            sib_fn.body().is_err()
226	                && sib_fn
227	                    .binding()
228	                    .and_then(|b| b.as_js_identifier_binding().cloned())
229	                    .and_then(|id| id.name_token().ok())
230	                    .is_some_and(|t| t.token_text_trimmed() == name)
231	        })
232	    })
233	}
