/// `never`, `any`, or `unknown` member.
///
/// The type resolver strips `never` from unions (`T | never` becomes `T`) and
/// lets `any`/`unknown` absorb the other variants, so a resolved type can no
/// longer reveal that one of these keywords was written. Checking the syntax
/// tree keeps such unions exempt regardless of how the resolver simplifies
/// them. Nested unions are looked through.
fn syntactic_union_is_exempt(ty: &AnyTsType) -> bool {
    let AnyTsType::TsUnionType(union) = ty.clone().omit_parentheses() else {
        return false;
    };
    union
        .types()
        .into_iter()
        .filter_map(|member| member.ok())
        .any(|member| {
            let member = member.omit_parentheses();
            matches!(
                member,
                AnyTsType::TsNeverType(_) | AnyTsType::TsAnyType(_) | AnyTsType::TsUnknownType(_)
            ) || syntactic_union_is_exempt(&member)
        })
}

