663	/// Builds a description like `"loading" | "idle"` from the inferred return
664	/// expression types, for use in a non-union annotation's diagnostic note.
665	///
666	/// Only string, number, and boolean literals are rendered; any other kind of
667	/// return type yields `None`, which produces the generic narrowing note.
668	fn build_inferred_description(returns: &[Type]) -> Option<String> {
669	    let mut out = String::new();
670	    let mut has_any = false;
671	    for ty in returns {
672	        let TypeData::Literal(lit) = &**ty else {
673	            return None;
674	        };
675	        if has_any {
676	            out.push_str(" | ");
677	        }
678	        has_any = true;
679	        match lit.as_ref() {
680	            Literal::String(s) => {
681	                let text = s.as_str();
682	                // Skip values that would look confusing in a diagnostic (e.g. "...").
683	                if text.contains("...")
684	                    || text.contains("__internal")
685	                    || text.contains("typeof import(")
686	                {
687	                    return None;
688	                }
689	                out.push('"');
690	                out.push_str(text);
691	                out.push('"');
692	            }
693	            Literal::Number(n) => out.push_str(n.as_str()),
694	            Literal::Boolean(b) => out.push_str(if b.as_bool() { "true" } else { "false" }),
695	            _ => return None,
696	        }
697	        // Skip overly long descriptions.
698	        if out.len() > MAX_DESCRIPTION_LENGTH {
699	            return None;
700	        }
701	    }
702	    if !has_any {
703	        return None;
704	    }
705	    Some(out)
706	}
